mapper.insert:
	/** [sql-materialsRelease.xml] MaterialsReleaseDmesMapper.insertDmes18 **/
    INSERT INTO DMES_18 (
        CHLLOT
        , CHLRTG
        , CHLDTS
        , CHLLIN
        , CHLHOU
        , CHLPNS
        , CHLQYS
        , CHLIDS
    ) VALUES (
        CASE WHEN #{st02Lot} = '' THEN CONCAT(TO_CHAR(SYSDATE, 'YYYYMMDD'), LPAD(#{st02Seq},5,'0')) ELSE #{st02Lot} END
        , 'I'
        , REPLACE(#{st03Dat},'-','')
        , #{line}
        , '1'
        , #{st02Code}
        , #{st02Moq}
        , 'LOTMGR'
    )
